// Static PKGBUILD reader. A PKGBUILD is bash, so only .SRCINFO (generated by makepkg --printsrcinfo) is
// authoritative; this reader extracts literal top-level assignments and simple $var / ${var} expansions
// and reports everything it could not resolve instead of guessing.

export interface PkgbuildFacts {
  scalars: Record<string, string>;
  arrays: Record<string, string[]>;
  /** pkgver() is defined: the real version is computed at build time. */
  dynamicPkgver: boolean;
  /** Function names defined at top level (build, package, package_foo, ...). */
  functions: string[];
  /** Entries whose expansion needed shell semantics (command substitution, ${x//a/b}, ...). */
  unresolved: string[];
}

function tokenizeArray(body: string): string[] {
  const out: string[] = [];
  let i = 0;
  while (i < body.length) {
    const c = body[i]!;
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (c === "#") {
      while (i < body.length && body[i] !== "\n") i++;
      continue;
    }
    let tok = "";
    while (i < body.length && !/\s/.test(body[i]!)) {
      const ch = body[i]!;
      if (ch === '"' || ch === "'") {
        const end = body.indexOf(ch, i + 1);
        if (end < 0) {
          tok += body.slice(i + 1);
          i = body.length;
        } else {
          tok += body.slice(i + 1, end);
          i = end + 1;
        }
      } else if (ch === "\\" && i + 1 < body.length) {
        tok += body[i + 1];
        i += 2;
      } else {
        tok += ch;
        i++;
      }
    }
    out.push(tok);
  }
  return out;
}

function expand(value: string, scalars: Record<string, string>, unresolved: string[]): string {
  return value.replace(/\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))|\$\{[^}]*\}|\$\(/g, (m, a, b) => {
    const name = a ?? b;
    if (name && Object.hasOwn(scalars, name)) return scalars[name]!;
    unresolved.push(m);
    return m;
  });
}

export function parsePkgbuild(text: string): PkgbuildFacts {
  const scalars: Record<string, string> = {};
  const arrays: Record<string, string[]> = {};
  const functions: string[] = [];
  const unresolved: string[] = [];
  const lines = text.split(/\r?\n/);
  let depth = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    const opens = (line.match(/\{/g) ?? []).length;
    const closes = (line.match(/\}/g) ?? []).length;
    if (depth === 0) {
      const fn = /^([A-Za-z_][A-Za-z0-9_]*)\s*\(\)\s*\{?/.exec(line);
      if (fn) {
        functions.push(fn[1]!);
        depth += opens - closes;
        continue;
      }
      const arr = /^([A-Za-z_][A-Za-z0-9_]*)=\(([\s\S]*)$/.exec(line);
      if (arr) {
        let body = arr[2]!;
        let j = i;
        while (!/\)\s*(#.*)?$/.test(body.trimEnd()) && j + 1 < lines.length) body += `\n${lines[++j]}`;
        i = j;
        arrays[arr[1]!] = tokenizeArray(body.replace(/\)\s*(#.*)?$/, "")).map(v => expand(v, scalars, unresolved));
        continue;
      }
      const scalar = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line);
      if (scalar) {
        const raw = scalar[2]!.replace(/\s+#.*$/, "").trim();
        const [value = ""] = tokenizeArray(raw);
        scalars[scalar[1]!] = expand(value, scalars, unresolved);
        continue;
      }
    }
    depth = Math.max(0, depth + opens - closes);
  }
  return { scalars, arrays, dynamicPkgver: functions.includes("pkgver"), functions, unresolved };
}

/** epoch:pkgver-pkgrel from a parsed PKGBUILD, or null when pkgver is computed at build time. */
export function pkgbuildVersion(f: PkgbuildFacts): string | null {
  const { pkgver, pkgrel, epoch } = f.scalars;
  if (!pkgver || f.dynamicPkgver) return null;
  return `${epoch && epoch !== "0" ? `${epoch}:` : ""}${pkgver}${pkgrel ? `-${pkgrel}` : ""}`;
}
